$localizedCopyField = static function (
    string $label,
    string $default,
    string $banglaDefault,
    string $type = 'text',
    ?string $help = null,
): array {
    $field = [
        'label' => $label,
        'type' => $type,
        'default' => $default,
        'localized_defaults' => ['bn' => $banglaDefault],
        'localized' => true,
        'public' => true,
    ];

    if ($help !== null) {
        $field['help'] = $help;
    }

    return $field;
};

